<script setup>
import { onMounted, onUnmounted, ref, watch } from 'vue'
import { LayoutDashboard, Plus, ArrowRight, LogOut, X, Layers, Archive } from 'lucide-vue-next'
import { useWorkboard } from './stores/workboard'
import SprintWorkspace from './components/SprintWorkspace.vue'
import KanbanBoard from './components/KanbanBoard.vue'
import TaskDialog from './components/TaskDialog.vue'
import BoardSettings from './components/BoardSettings.vue'
import FlowMetrics from './components/FlowMetrics.vue'
import NotificationsPanel from './components/NotificationsPanel.vue'
import InfoTooltip from './components/InfoTooltip.vue'
import PasswordRecovery from './components/PasswordRecovery.vue'
import AccountDialog from './components/AccountDialog.vue'
const store=useWorkboard()
const username=ref(''),password=ref(''),register=ref(false),view=ref('kanban'),sprintFilter=ref('all')
const params=new URLSearchParams(location.search),resetUid=ref(params.get('reset_uid')),resetToken=ref(params.get('reset_token')),recovery=ref(!!params.get('reset_uid')),accountOpen=ref(false),email=ref('')
if(params.has('reset_uid'))history.replaceState({},'',location.pathname)
function closeRecovery(){if(resetUid.value)store.user=null;recovery.value=false;resetUid.value=null;resetToken.value=null}
const modal=ref(null),title=ref(''),description=ref(''),kind=ref('backlog'),wip=ref(''),taskModal=ref(null)
let refreshTimer
onMounted(async()=>{await store.init();refreshTimer=setInterval(()=>{if(store.user && !store.busy && store.connection!=='connected')store.load().catch(()=>{})},20000)})
onUnmounted(()=>clearInterval(refreshTimer))
watch(()=>store.selected,(id,previous)=>{if(previous!==null){taskModal.value=null;modal.value=null}view.value='kanban';sprintFilter.value='all'})
function open(type) {modal.value=type;title.value='';description.value='';kind.value='backlog';wip.value='';store.error=''}
async function editTask(task) {await store.run(async()=>{const full=await store.fetchTask(task.id);taskModal.value={task:full,column:full.column,sprint:full.sprint}})}
function newTask(column=store.board?.columns[0]?.id,sprint=null) {taskModal.value={task:null,column,sprint};store.error=''}
function showSprint(id) {sprintFilter.value=id;view.value='kanban'}
async function save() {await store.run(async()=>{if(modal.value==='board'){const created=await store.mutate('boards/','POST',{title:title.value,description:description.value});store.selected=created.id}else await store.mutate('columns/','POST',{board:store.selected,title:title.value,position:store.board.columns.length,kind:kind.value,wip_limit:wip.value===''?null:Number(wip.value)});modal.value=null})}
</script>
<template>
  <div v-if="!store.user || recovery" class="auth-page"><section class="auth-story"><div class="brand"><Layers/> WorkBoard<span class="brand-dot">.</span></div><span class="eyebrow">MENOS RUÍDO. MAIS PROGRESSO.</span><h1>Grandes ideias.<br>Um passo<br><em>de cada vez.</em></h1><p>Um espaço para organizar suas tarefas, visualizar o trabalho e tirar seus projetos do papel.</p><div class="mini-board"><div v-for="(label,i) in ['Planejar','Construir','Entregar']" :key="label"><small>{{label}}</small><span v-for="n in 3-i" :key="n" :class="{accent:i===1}"></span></div></div><footer>Feito para quem gosta de fazer acontecer.</footer></section><PasswordRecovery v-if="recovery" :uid="resetUid" :token="resetToken" @close="closeRecovery"/><section v-else class="auth-form"><span class="eyebrow">SEU PRÓXIMO PROJETO COMEÇA AQUI</span><h2>{{register?'Crie seu espaço':'Bom ter você por aqui'}}</h2><p>{{register?'Cadastre-se e organize seu primeiro quadro.':'Entre na sua conta para continuar.'}}</p><form @submit.prevent="store.auth(username,password,register,email)"><label>Usuário<input v-model="username" required maxlength="150" autocomplete="username" placeholder="Seu nome de usuário"></label><label v-if="register">E-mail<input v-model="email" type="email" required autocomplete="email"></label><label>Senha<input v-model="password" required type="password" :autocomplete="register?'new-password':'current-password'" placeholder="Sua senha" :minlength="register?8:1"></label><p v-if="store.error" class="error" role="alert">{{store.error}}</p><button class="primary" :disabled="store.busy">{{store.busy?'Aguarde…':register?'Criar conta':'Entrar no WorkBoard'}}<ArrowRight :size="18"/></button></form><button v-if="!register" class="text-button" @click="recovery=true">Esqueci minha senha</button><button class="text-button" @click="register=!register">{{register?'Já tenho uma conta. Entrar':'Ainda não tem conta? Cadastre-se'}}</button></section></div>
  <div v-else class="app-layout"><aside><div class="brand"><Layers/> WorkBoard<span class="brand-dot">.</span></div><div class="workspace"><div class="avatar">{{store.user.username[0]?.toUpperCase()}}</div><div><strong>Meu espaço</strong><small>Workspace colaborativo</small></div></div><div class="nav-heading">SEUS QUADROS<button aria-label="Criar quadro" @click="open('board')"><Plus :size="18"/></button></div><nav><button v-for="board in store.boards" :key="board.id" :class="{active:store.selected===board.id}" @click="store.selected=board.id"><Archive v-if="board.archived" :size="17"/><LayoutDashboard v-else :size="18"/>{{board.title}}</button></nav><button v-if="store.boardsNext" class="new-board" :disabled="store.busy" @click="store.moreBoards">Carregar mais quadros</button><button class="new-board" @click="open('board')"><Plus :size="17"/> Novo quadro</button><div class="sidebar-bottom"><div class="tip"><span>UM PASSO POR VEZ</span><p>Clareza para planejar.<br>Espaço para criar.</p></div><button class="logout" @click="store.signOut" :disabled="store.busy"><LogOut :size="17"/> Sair da conta</button></div></aside><main><header><span>Workspace <span class="slash">/</span><strong>{{store.board?.title ?? 'Seus projetos'}}</strong></span><div class="header-right"><NotificationsPanel @open-task="editTask"/><button class="user-badge" aria-label="Minha conta" @click="accountOpen=true">{{store.user.username}}</button><button class="mobile-logout" aria-label="Sair da conta" @click="store.signOut"><LogOut :size="17"/></button></div></header><section class="board-heading"><div><span class="eyebrow">ORGANIZE. CONSTRUA. ENTREGUE.</span><h1>{{store.board?.title ?? 'Seu próximo grande projeto'}}</h1><p>{{store.board?.description || 'Transforme suas ideias em próximos passos.'}}</p></div><button v-if="!store.board || store.canWrite" class="primary" @click="store.board?newTask():open('board')" :disabled="store.busy || (!!store.board && !store.board.columns.length)"><Plus :size="18"/>{{store.board?'Nova tarefa':'Criar quadro'}}</button></section><p v-if="store.error" class="error global-error" role="alert">{{store.error}}<button aria-label="Limpar erro" @click="store.error=''"><X :size="16"/></button></p><div v-if="store.board?.archived" class="board-banner">Quadro arquivado. Consulte o histórico ou desarquive em Configurações.</div><div v-else-if="store.board?.role==='viewer'" class="board-banner">Você tem acesso de leitura a este quadro.</div><template v-if="store.board"><div class="toolbar"><div class="view-tabs"><button :class="{active:view==='kanban'}" @click="view='kanban'"><LayoutDashboard :size="17"/> Visão Kanban</button><button :class="{active:view==='sprints'}" @click="view='sprints'">Sprints</button><button :class="{active:view==='retro'}" @click="view='retro'">Retrospectiva</button><button :class="{active:view==='metrics'}" @click="view='metrics'">Métricas</button><button :class="{active:view==='settings'}" @click="view='settings'">Configurações</button></div></div><KanbanBoard v-if="view==='kanban'" :key="`${store.selected}-${sprintFilter}`" :sprint="sprintFilter" @open-task="editTask" @new-task="newTask" @new-column="open('column')" @settings="view='settings'"/><SprintWorkspace v-else-if="view==='sprints' || view==='retro'" :key="store.selected" :mode="view" @show-sprint="showSprint"/><FlowMetrics v-else-if="view==='metrics'" :key="store.selected"/><BoardSettings v-else :key="store.selected" @open-task="editTask"/></template><div v-else class="empty-state"><LayoutDashboard :size="48"/><h2>Ideias precisam de espaço.</h2><p>Crie seu primeiro quadro. As colunas iniciais ficam por nossa conta.</p><button class="primary" @click="open('board')"><Plus :size="18"/> Criar meu primeiro quadro</button></div><footer class="main-footer">WorkBoard <span>{{store.busy?'Salvando alterações…':'Seu trabalho, em movimento.'}}</span></footer></main></div>
  <AccountDialog v-if="accountOpen && store.user" @close="accountOpen=false"/><TaskDialog v-if="taskModal && store.board" :task="taskModal.task" :column="taskModal.column" :sprint="taskModal.sprint" @close="taskModal=null"/>
  <div v-if="modal" class="modal-backdrop" @click.self="!store.busy && (modal=null)" @keydown.esc="!store.busy && (modal=null)"><section v-dialog class="modal" role="dialog" aria-modal="true" aria-labelledby="basic-modal-title"><div class="modal-heading"><h2 id="basic-modal-title">{{modal==='board'?'Novo quadro':'Nova coluna'}}</h2><button aria-label="Fechar" :disabled="store.busy" @click="modal=null"><X :size="20"/></button></div><form @submit.prevent="save"><label>Título<input v-model="title" required autofocus :maxlength="modal==='column'?80:120" placeholder="O que vamos construir?"></label><label v-if="modal==='board'">Descrição<textarea v-model="description" maxlength="2000" rows="3"></textarea></label><template v-else><label>Tipo de coluna<select v-model="kind"><option value="backlog">A fazer</option><option value="progress">Em execução</option><option value="done">Concluída</option></select></label><div class="label-field"><div class="label-caption"><label for="new-column-wip">Limite WIP</label><InfoTooltip label="O que significa WIP?" text="WIP significa Work in Progress (trabalho em andamento). É o limite de tarefas simultâneas na coluna. Exemplo: com limite 3, uma quarta tarefa só entra quando uma das três sair. Deixe vazio para não limitar."/></div><input id="new-column-wip" v-model="wip" type="number" min="1" placeholder="Sem limite"></div></template><p v-if="store.error" class="error" role="alert">{{store.error}}</p><button class="primary" :disabled="store.busy">{{store.busy?'Salvando…':'Salvar'}}</button></form></section></div>
  <div v-if="store.notice" class="undo-toast" role="status"><span>{{store.notice}}</span><button v-if="store.undo" :disabled="store.busy" @click="store.undoLast">Desfazer</button><button aria-label="Fechar aviso" @click="store.notice='';store.undo=null"><X :size="16"/></button></div>
</template>
